u0915 \\u0930\\u0940\\u091c\\u0928\\u093f\\u0902\\u0917 (Algorithmic Reasoning)*: \\u0909\\u0926\\u093e. \\u092c\\u0942\\u0932\\u093f\\u092f\\u0928 \\u090f\\u0915\\u094d\\u0938\\u092a\\u094d\\u0930\\u0947\\u0936\\u0928, \\u0921\\u093e\\u0907\\u0928\\u0947\\u0917\\u0935\\u0948\\u0932, \\u0935\\u0947\\u092c \\u0911\\u092b \\u0932\\u093e\\u0907\\u091c\\u0964\\n  2. *\\u0905\\u0930\\u093f\\u0925\\u092e\\u0947\\u091f\\u093f\\u0915 \\u0930\\u0940\\u091c\\u0928\\u093f\\u0902\\u0917 (Arithmetic Reasoning)*: \\u092e\\u0932\\u094d\\u091f\\u0940-\\u0938\\u094d\\u091f\\u0947\\u092a \\u0917\\u0923\\u093f\\u0924\\u0940\\u092f \\u0938\\u092e\\u0938\\u094d\\u092f\\u093e \\u0938\\u092e\\u093e\\u0927\\u093e\\u0928\\u0964\\n  3. *\\u0928\\u0947\\u091a\\u0941\\u0930\\u0932 \\u0932\\u0948\\u0902\\u0917\\u094d\\u0935\\u0947\\u091c \\u0905\\u0902\\u0921\\u0930\\u0938\\u094d\\u091f\\u0948\\u0902\\u0921\\u093f\\u0902\\u0917 (NLU)*: \\u0924\\u093e\\u0930\\u094d\\u0915\\u093f\\u0915 \\u0905\\u0928\\u0941\\u092e\\u093e\\u0928, \\u0930\\u0942\\u092a\\u0915 \\u0938\\u092e\\u091d\\u0964\\n  4. *\\u0935\\u0930\\u094d\\u0932\\u094d\\u0921 \\u0928\\u0949\\u0932\\u0947\\u091c (World Knowledge)*: \\u0924\\u0925\\u094d\\u092f\\u093e\\u0924\\u094d\\u092e\\u0915 \\u091c\\u094d\\u091e\\u093e\\u0928 \\u0914\\u0930 \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f \\u091c\\u094d\\u091e\\u093e\\u0928 \\u0924\\u0930\\u094d\\u0915\\u0964\\n  5. *\\u092c\\u0939\\u0941\\u092d\\u093e\\u0937\\u0940 \\u0915\\u093e\\u0930\\u094d\\u092f (Multilingual Tasks)*: \\u092c\\u0939\\u0941\\u092d\\u093e\\u0937\\u0940 \\u0938\\u092e\\u091d \\u0914\\u0930 \\u0905\\u0928\\u0941\\u0935\\u093e\\u0926/\\u0924\\u0930\\u094d\\u0915\\u0964\\n\\n---\\n\\n### 3. \\u0924\\u0941\\u0932\\u0928\\u093e\\u0924\\u094d\\u092e\\u0915 \\u0905\\u0932\\u093e\\u0907\\u0928\\u092e\\u0947\\u0902\\u091f \\u0935\\u093f\\u0927\\u093f\\u092f\\u093e\\u0901 (Alignment Criteria Formulations)\\n(`setup_10`, `setup_11`)\\n\\n\\u092e\\u0949\\u0921\\u0932 \\u092