a\\u0932-\\u091a\\u0949\\u0907\\u0938 \\u091f\\u093e\\u0938\\u094d\\u0915 \\u092e\\u0947\\u0902:** \\u0915\\u0947\\u0935\\u0932 \\u0924\\u092d\\u0940 \\u0938\\u0939\\u0940 \\u092e\\u093e\\u0928\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948 \\u091c\\u092c \\u0928\\u093f\\u0915\\u093e\\u0932\\u093e \\u0917\\u092f\\u093e \\u0932\\u0947\\u092c\\u0932 (\\u091c\\u0948\\u0938\\u0947 \\\"B\\\" \\u092f\\u093e \\u092a\\u0942\\u0930\\u093e \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u091f\\u0947\\u0915\\u094d\\u0938\\u094d\\u091f) \\u0917\\u094d\\u0930\\u093e\\u0909\\u0902\\u0921-\\u091f\\u094d\\u0930\\u0941\\u0925 \\u0938\\u0947 \\u0936\\u0924-\\u092a\\u094d\\u0930\\u0924\\u093f\\u0936\\u0924 \\u092e\\u0947\\u0932 \\u0916\\u093e\\u0924\\u093e \\u0939\\u094b\\u0964\\n\\n#### B. \\u092a\\u094d\\u0930\\u0938\\u094d\\u0924\\u093e\\u0935\\u093f\\u0924 \\u0935\\u093f\\u0927\\u093f: Minimum Edit Distance (MinED)\\n1. **\\u0926\\u0942\\u0930\\u0940 \\u0917\\u0923\\u0928\\u093e:** \\u092a\\u094d\\u0930\\u0947\\u0921\\u093f\\u0915\\u094d\\u091f\\u0947\\u0921 \\u091f\\u0947\\u0915\\u094d\\u0938\\u094d\\u091f $y_{\\\\text{pred}}$ \\u0914\\u0930 \\u0938\\u0902\\u092d\\u093e\\u0935\\u093f\\u0924 \\u0932\\u0915\\u094d\\u0937\\u094d\\u092f\\u094b\\u0902/\\u0935\\u093f\\u0915\\u0932\\u094d\\u092a\\u094b\\u0902 $C = \\\\{c_1, c_2, \\\\dots, c_k\\\\}$ \\u0915\\u0947 \\u092c\\u0940\\u091a \\u0932\\u0947\\u0935\\u0947\\u0928\\u0936\\u094d\\u091f\\u093e\\u0907\\u0928 \\u0926\\u0942\\u0930\\u0940 (Levenshtein Distance) $D(y_{\\\\text{pred}}, c_i)$ \\u0915\\u0940 \\u0917\\u0923\\u0928\\u093e\\u0964\\n2. **\\u0905\\u0932\\u093e\\u0907\\u0928\\u092e\\u0947\\u0902\\u091f \\u0928\\u093f\\u092f\\u092e:**\\n   $$\\\\hat{c} = \\\\arg\\\\min_{c_i \\\\in C} \\\\frac{D(y_{\\\\text{pred}}, c_i)}{\\\\max(|y_{\\\\text{pred}}|, |c_i|)}$$\\n   - **\\u092e\\u0932\\u094d\\u091f\\u0940\\u092a\\u0932-\\u091a\\u0949\\u0907\\u0938 \\u091f\\u093e\\u0938\\u094d\\u0915:** \\u091c\\u0928\\u0930\\u0947\\u091f\\u0947\\u0921 \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0915\\u094b \\u0909\\u0938 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u0938\\u0947 \\u092e\\u0948\\u092a \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u0924\\u093e \\u0939\\u0948 \\u091c\\u093f\\u0938\\u0915\\u0940 \\u090f\\u0921\\u093f\\u091f \\u0926\\u0942\\u0930\\u0940 \\u0928\\u094d\\u092f\\u0942\\u0928\\u0924\\u092e \\u0939\\u094b\\u0964 \\u092f\\u0926\\u093f \\u0926\\u0942\\u0930\\u0940 \\u090f\\u0915 \\u092a\\u0942\\u0930\\u094d\\u0935-\\u0928\\u093f\\u0930\\u094d\\u0927\\u093e\\u0930\\u093f\\u0924 \\u0925\\u094d\\u0930\\u0947\\u0936\\u094b\\u0932\\u094d\\u0921 $\\\\tau$ (\\u0909\\u0926\\u093e. $\\\\le 0.3$ \\u0938\\u093e\\u092e\\u093e\\u0928\\u094d\\u092f\\u0940\\u0915\\u0943\\u0924 \\u0926\\u0942\\u0930\\u0940) \\u0915\\u0947 \\u092d\\u0940\\u0924\\u0930 \\u0939\\u0948, \\u0924\\u094b \\u0909\\u0938\\u0947 \\u0909\\u0938 \\u0935\\u093f\\u0915\\u0932\\u094d\\u092a \\u0915\\u093e \\u091a\\u092f\\u0928 \\u092e\\u093e\\u0928\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\\n   - **\\u092b\\u094d\\u0930\\u0940-\\u092b\\u0949\\u0930\\u094d\\u092e \\u091f\\u093e\\u0938\\u094d\\u0915:** \\u0928\\u093f\\u0915\\u093e\\u0932\\u0947 \\u0917\\u090f \\u0909\\u0924\\u094d\\u0924\\u0930 \\u0914\\u0930 \\u0917\\u094d\\u0930\\u093e\\u0909\\u0902\\u0921-\\u091f\\u094d\\u0930\\u0941\\u0925 \\u0915\\u0947 \\u092c\\u0940\\u091a \\u0915\\u0940 \\u0926\\u0942\\u0930\\u0940 \\u092f\\u0926\\u093f \\u0936\\u0942\\u0928\\u094d\\u092f \\u092f\\u093e \\u0925\\u094d\\u0930\\u0947\\u0936\\u094b\\u0932\\u094d\\u0921 $\\\\tau$ \\u0915\\u0947 \\u092d\\u0940\\u0924\\u0930 \\u0939\\u0948, \\u0924\\u094b \\u0909\\u0938\\u0947 \\u0938\\u0939\\u0940 \\u092e\\u093e\\u0928\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964\\n\\n---\\n\\n### 4. \\u092a\\u094d\\u0930\\u093e\\u092f\\u094b\\u0917\\u093f\\u0915 \\u0928\\u093f\\u092f\\u0902\\u0924\\u094d\\u0930\\u0923 \\u090f\\u0935\\u0902 \\u0928\\u093f\\u0937\\u094d\\u092a\\u0915\\u094d\\u0937\\u0924\\u093e (Experimental Controls & Reproducibility)\\n1. **\\u092b\\u094d\\u0930\\u094b\\u091c\\u0928 \\u092e\\u0949\\u0921\\u0932 \\u0906\\u0909\\u091f\\u092a\\u0941\\u091f (Frozen Outputs Control):**\\n   - \\u0926\\u094b\\u0928\\u094b\\u0902 \\u0935\\u093f\\u0927\\u093f\\u092f\\u094b\\u0902 (EM \\u0914\\u0930 MinED) \\u0915\\u093e \\u092e\\u0942\\u0932\\u094d\\u092f\\u093e\\u0902\\u0915\\u0928 \\u092e\\u0949\\u0921\\u0932 \\u0926\\u094d\\u0935\\u093e\\u0930\\u093e \\u0909\\u0924\\u094d\\u092a\\u0928\\u094d\\u0928 **\\u0938\\u092e\\u093e\\u0928 \\u0906\\u0909\\u091f\\u092a\\u0941\\u091f \\u0938\\u0947\\u091f\\u094d\\u0938** \\u092a\\u0930 \\u0915\\u093f\\u092f\\u093e \\u091c\\u093e\\u090f\\u0917\\u093e\\u0964 \\u092e\\u0949\\u0921\\u0932 \\u0915\\u094b \\u0926\\u094b\\u092c\\u093e\\u0930\\u093e \\u0930\\u0928 \\u0915\\u0930\\u0928\\u0947 \\u0915\\u0940 \\u0906\\u0935\\u0936\\u094d\\u092f\\u0915\\u0924\\u093e \\u0928\\u0939\\u0940\\u0902 \\u0939\\u094b\\u0917\\u0940, \\u091c\\u093f\\u0938\\u0938\\u0947 \\u0930\\u0948\\u0902\\u0921\\u092e \\u0938\\u0948\\u0902\\u092a\\u0932\\u093f\\u0902\\u0917 \\u0915\\u093e \\u0915\\u094b\\u0908 \\u092a\\u094d\\u0930\\u092d\\u093e\\u0935 \\u0928\\u0939\\u0940\\u0902 \\u092a\\u0921\\u093c\\u0947\\u0917\\u093e\\u0964\\n2. **\\u0921\\u093f\\u091f\\u0930\\u092e\\u093f\\u0928\\u093f\\u0938\\u094d\\u091f\\u093f\\u0915 \\u091c\\u0928\\u0930\\u0947\\u0936\\u0928 (Deterministic Decoding):**\\n   - \\u092e\\u0949\\u0921\\u0932 \\u0907\\u0928\\u094d\\u092b\\u0930\\u0947\\u0902\\u0938 \\u092e\\u0947\\u0902 \\u0917\\u094d\\u0930\\u0940\\u0921\\u0940 \\u0921\\u0940\\u0915\\u094b\\u0921\\u093f\\u0902\\u0917 (`temperature = 0.0`, `top_p = 1.0`) \\u0915\\u093e \\u0909\\u092a\\u092f\\u094b\\u0917\\u0964\\n3. **\\u092e\\u093e\\u0928\\u0915 \\u092a\\u094d\\u0930\\u0949\\u092e\\u094d\\u091f\\u093f\\u0902\\u0917 \\u092a\\u094d\\u0930\\u094b\\u091f\\u094b\\u0915\\u0949\\u0932:**\\n   - \\u0938\\u092d\\u0940 \\u0915\\u093e\\u0930\\u094d\\u092f\\u094b\\u0902 \\u09